Query Text:
SELECT
  (
    (
      'DSAR' = 'DSAR'
      AND (
        (
          'RBAC_ABAC' = 'RBAC_ABAC' AND 'org_123' IN (
            SELECT
              'org_123'
          )
        )
        OR 1 = 1
      )
    )
  ) AS permission_check_result
LIMIT 100

SELECT
  (
    'DISABLE' = 'DISABLE'
    OR (
      'DSAR' <> 'DSAR' AND ARRAY_CONTAINS(ARRAY['DSAR', 'ASSESSMENT'], 'DSAR')
    )
    OR (
      'DSAR' = 'DSAR'
      AND (
        (
          'RBAC_ABAC' = 'RBAC_ABAC' AND 'org_123' IN (
            SELECT
              'org_123'
          )
        )
        OR 1 = 1
      )
    )
  ) AS permission_check_result
LIMIT 100
